        assert!(
            outcome.is_some(),
            "a window whose hash still matches must commit"
        );
        drop(nest);
        let store = Store::open(&d.path().join(DB_FILE)).unwrap();
        assert_eq!(store.entity_keys().unwrap().len(), 1);
        assert_eq!(
            store.get_block_hash(10).unwrap().as_deref(),
            Some("0xcanonical")
        );
