    /// A provider that serves logs and timestamps and cannot answer `eth_getBlockByNumber` for a hash.
    struct NoBlockHash;

    #[async_trait::async_trait]
    impl Source for NoBlockHash {
        async fn tip(&self) -> Result<u64> {
            Ok(100)
        }
        async fn block_hash(&self, _n: u64) -> Result<Option<String>> {
            anyhow::bail!("eth_getBlockByNumber: method not available")
        }
        async fn logs(
            &self,
            _filter: &crate::source::LogFilter,
            _from: u64,
            _to: u64,
        ) -> Result<Vec<crate::rpc::Log>> {
            Ok(Vec::new())
        }
        async fn block_timestamps(
            &self,
            blocks: &[u64],
        ) -> Result<std::collections::HashMap<u64, u64>> {
            Ok(blocks.iter().map(|&b| (b, b * 1000)).collect())
        }
    }

    /// #1666. Windows kept committing with no checkpoint, so reorg detection answered None for ever,
    /// and nothing said so above debug. Ingestion carries on; the miss is counted where an alert can
    /// read it.
    #[tokio::test]
    async fn a_window_committed_without_a_checkpoint_is_counted() {
        let addr = "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48";
        let d = tempfile::tempdir().unwrap();
        let mut nest = build_test_nest(d.path(), addr).await;
        nest.metrics = Arc::new(crate::metrics::NestMetrics::default());
        for b in [10u64, 11] {
            let outcome = nest
                .process_window(&NoBlockHash, &[transfer_log(b, 0)], b, b, 100)
                .await
                .unwrap();
            assert!(outcome.is_some(), "a missing checkpoint stopped ingestion");
        }
        assert_eq!(nest.store.get_block_hash(11).unwrap(), None);
        assert_eq!(
            nest.metrics.checkpoints_missed(),
            2,
            "two windows committed with no reorg checkpoint and nothing counted them"
        );
    }

    /// RFC-0004 §3: the pipelined (concurrent-fetch) backfill produces **byte-identical** segments to
    /// the sequential path - concurrency overlaps latency without changing the output.
    #[tokio::test]
    async fn pipelined_backfill_matches_sequential() {
        use crate::registry::{ContractSpec, DecodeRegistry};
        const ERC20: &str = r#"[{"type":"event","name":"Transfer","inputs":[
            {"name":"from","type":"address","indexed":true},
            {"name":"to","type":"address","indexed":true},
            {"name":"value","type":"uint256","indexed":false}],"anonymous":false}]"#;
        let abi: alloy_json_abi::JsonAbi = serde_json::from_str(ERC20).unwrap();
        let addr: alloy_primitives::Address = "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48"
            .parse()
            .unwrap();
        let reg = DecodeRegistry::build(vec![ContractSpec {
            alias: "usdc".into(),
            address: addr,
            abi,
            events: Vec::new(),
        }])
        .unwrap();

        let logs: Vec<_> = (10u64..40)
            .flat_map(|b| [transfer_log(b, 0), transfer_log(b, 1)])
            .collect();
        let source = MockSource { logs };
        let addresses: Vec<String> = reg
            .addresses()
            .iter()
            .map(|a| format!("0x{}", hex::encode(a)))
            .collect();
        let topic0s: Vec<String> = reg
            .topic0s()
            .iter()
            .map(|t| format!("0x{}", hex::encode(t)))
            .collect();

        let d_seq = tempfile::tempdir().unwrap();
        let seq = backfill_direct(
            &source,
            &reg,
            d_seq.path(),
            &addresses,
            &topic0s,
            &[],
            None,
            0,
            10,
            39,
            5,
            SPAN_OFF,
            true,
        )
        .await
        .unwrap();
        let d_pipe = tempfile::tempdir().unwrap();
        let pipe = backfill_direct_pipelined(
            &source,
            &reg,
            d_pipe.path(),
            &addresses,
            &topic0s,
            &[],
            None,
            0,
            10,
            39,
            5,
            SPAN_OFF,
            8,
            |_| Ok(()),
            |_, _, _| {},
        )
        .await
        .unwrap();

        assert_eq!(seq, pipe, "same event count");
        assert!(seq > 0);
        let hashes = |dir: &std::path::Path| -> Vec<(String, String)> {
            let m = seal::load_manifest(dir).unwrap();
            m.tables
                .iter()
                .flat_map(|(t, segs)| segs.iter().map(move |s| (t.clone(), s.hash.clone())))
                .collect()
        };
        assert_eq!(
            hashes(d_seq.path()),
            hashes(d_pipe.path()),
            "concurrency must not change the sealed bytes"
        );
    }

    /// A provider with a result cap: a range over `cap` logs is refused the way Alchemy refuses it.
    struct ResultCapSource {
        logs: Vec<crate::rpc::Log>,
        cap: usize,
        calls: std::sync::Mutex<Vec<(u64, u64)>>,
        max_calls: usize,
    }

    impl ResultCapSource {
        fn new(logs: Vec<crate::rpc::Log>, cap: usize) -> Self {
            Self {
                logs,
                cap,
                calls: Default::default(),
                max_calls: 500,
            }
        }
    }

    #[async_trait::async_trait]
    impl Source for ResultCapSource {
        async fn tip(&self) -> Result<u64> {
            Ok(self.logs.iter().map(|l| l.block_number).max().unwrap_or(0))
        }
        async fn block_hash(&self, _n: u64) -> Result<Option<String>> {
            Ok(None)
        }
        async fn logs(
            &self,
            _filter: &crate::source::LogFilter,
            from: u64,
            to: u64,
        ) -> Result<Vec<crate::rpc::Log>> {
            // A backfill that stops advancing never yields to a timeout, so it is stopped here.
            let asked = {
                let mut calls = self.calls.lock().unwrap();
                calls.push((from, to));
                calls.len()
            };
            assert!(
                asked < self.max_calls,
                "{asked} getLogs calls: the backfill is not advancing"
            );
            // Pending once, as a request does, so windows in flight can land while another is fetched.
            tokio::task::yield_now().await;
            let lo = self.logs.partition_point(|l| l.block_number < from);
            let hi = self.logs.partition_point(|l| l.block_number <= to);
            if hi - lo > self.cap {
                anyhow::bail!("query returned more than 10000 results");
            }
            Ok(self.logs[lo..hi].to_vec())
        }
        async fn block_timestamps(
            &self,
            blocks: &[u64],
        ) -> Result<std::collections::HashMap<u64, u64>> {
            Ok(blocks.iter().map(|&b| (b, b * 1000)).collect())
        }
    }

    /// #1671: a window the controller grew over an empty range lands on dense history whole. The
    /// provider's cap bounds one response, but the splitter used to merge every piece, so one
    /// in-flight window held width x density rows however wide it had grown.
    #[tokio::test]
    async fn a_window_grown_over_an_empty_range_does_not_materialise_dense_history_whole() {
        use crate::registry::{ContractSpec, DecodeRegistry};
        const ERC20: &str = r#"[{"type":"event","name":"Transfer","inputs":[
            {"name":"from","type":"address","indexed":true},
            {"name":"to","type":"address","indexed":true},
            {"name":"value","type":"uint256","indexed":false}],"anonymous":false}]"#;
        let abi: alloy_json_abi::JsonAbi = serde_json::from_str(ERC20).unwrap();
        let reg = DecodeRegistry::build(vec![ContractSpec {
            alias: "usdc".into(),
            address: "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48"
                .parse()
                .unwrap(),
            abi,
            events: Vec::new(),
        }])
        .unwrap();
        let addresses: Vec<String> = reg
            .addresses()
            .iter()
            .map(|a| format!("0x{}", hex::encode(a)))
            .collect();
        let topic0s: Vec<String> = reg
            .topic0s()
            .iter()
            .map(|t| format!("0x{}", hex::encode(t)))
            .collect();

        // Empty to 200,000, then 15,000 blocks at three logs each. From a 1,000-block start the
        // window reaches 100,000 by block 185,000, so one window spans the whole dense run.
        let logs: Vec<_> = (200_001u64..=215_000)
            .flat_map(|b| (0..3).map(move |li| transfer_log(b, li)))
            .collect();

        for concurrency in [1, 4] {
            let d = tempfile::tempdir().unwrap();
            let mut widest = 0u64;
            let total = backfill_direct_pipelined(
                &ResultCapSource::new(logs.clone(), 1_000),
                &reg,
                d.path(),
                &addresses,
                &topic0s,
                &[],
                None,
                0,
                0,
                215_000,
                1_000,
                SPAN_OFF,
                concurrency,
                |_| Ok(()),
                |_, n, _| widest = widest.max(n),
            )
            .await
            .unwrap();
            assert_eq!(total, 45_000, "{concurrency}-way: every row once");
            assert!(
                widest <= 20_000,
                "{concurrency}-way: one window carried {widest} rows against a budget of 20,000"
            );
            let d_seq = tempfile::tempdir().unwrap();
            backfill_direct(
                &ResultCapSource::new(logs.clone(), 1_000),
                &reg,
                d_seq.path(),
                &addresses,
                &topic0s,
                &[],
                None,
                0,
                0,
                215_000,
                1_000,
                SPAN_OFF,
                true,
            )
            .await
            .unwrap();
            let hashes = |dir: &std::path::Path| -> Vec<(String, String)> {
                let m = seal::load_manifest(dir).unwrap();
                m.tables
                    .iter()
                    .flat_map(|(t, segs)| segs.iter().map(move |s| (t.clone(), s.hash.clone())))
                    .collect()
            };
            assert_eq!(
                hashes(d.path()),
                hashes(d_seq.path()),
                "{concurrency}-way: a cut window must seal the same bytes"
            );
        }
    }

    /// #1671: the rest of a cut window must start where the cut fell. Asking for the overlap again
    /// re-fills the budget from the same two blocks and never advances.
    #[tokio::test]
    async fn the_rest_of_a_cut_window_advances_past_a_block_that_fills_the_budget() {
        use crate::registry::{ContractSpec, DecodeRegistry};
        const ERC20: &str = r#"[{"type":"event","name":"Transfer","inputs":[
            {"name":"from","type":"address","indexed":true},
            {"name":"to","type":"address","indexed":true},
            {"name":"value","type":"uint256","indexed":false}],"anonymous":false}]"#;
        let abi: alloy_json_abi::JsonAbi = serde_json::from_str(ERC20).unwrap();
        let reg = DecodeRegistry::build(vec![ContractSpec {
            alias: "usdc".into(),
            address: "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48"
                .parse()
                .unwrap(),
            abi,
            events: Vec::new(),
        }])
        .unwrap();
        let addresses: Vec<String> = reg
            .addresses()
            .iter()
            .map(|a| format!("0x{}", hex::encode(a)))
            .collect();
        let topic0s: Vec<String> = reg
            .topic0s()
            .iter()
            .map(|t| format!("0x{}", hex::encode(t)))
            .collect();
        // Each block alone fills the budget, and the provider will not serve 10..=11 together. Block 11
        // is already buffered when the final pass is cut at 10, so it must not seal before the rest.
        let logs: Vec<_> = (0..20_000)
            .map(|li| transfer_log(10, li))
            .chain((0..20_000).map(|li| transfer_log(11, li)))
            .collect();
        let source = ResultCapSource::new(logs, 30_000);
        let d = tempfile::tempdir().unwrap();
        let total = backfill_direct_pipelined(
            &source,
            &reg,
            d.path(),
            &addresses,
            &topic0s,
            &[],
            None,
            0,
            10,
            11,
            1_000,
            SPAN_OFF,
            1,
            |_| Ok(()),
            |_, _, _| {},
        )
        .await
        .unwrap();
        assert_eq!(total, 40_000, "every row once");
        let m = seal::load_manifest(d.path()).unwrap();
        let sealed: usize = m.tables.values().flatten().map(|s| s.rows).sum();
        assert_eq!(sealed, 40_000, "every row sealed once");
    }

    /// #1671, review: a served piece is cut to what is left of the budget. Two 15,000-log halves of a
    /// refused range would otherwise come back together, 30,000 against a budget of 20,000.
    #[tokio::test]
    async fn a_served_piece_is_cut_to_the_budget_that_is_left() {
        use crate::registry::{ContractSpec, DecodeRegistry};
        const ERC20: &str = r#"[{"type":"event","name":"Transfer","inputs":[
            {"name":"from","type":"address","indexed":true},
            {"name":"to","type":"address","indexed":true},
            {"name":"value","type":"uint256","indexed":false}],"anonymous":false}]"#;
        let abi: alloy_json_abi::JsonAbi = serde_json::from_str(ERC20).unwrap();
        let reg = DecodeRegistry::build(vec![ContractSpec {
            alias: "usdc".into(),
            address: "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48"
                .parse()
                .unwrap(),
            abi,
            events: Vec::new(),
        }])
        .unwrap();
        let addresses: Vec<String> = reg
            .addresses()
            .iter()
            .map(|a| format!("0x{}", hex::encode(a)))
            .collect();
        let topic0s: Vec<String> = reg
            .topic0s()
            .iter()
            .map(|t| format!("0x{}", hex::encode(t)))
            .collect();
        // 1,500 logs in each of blocks 10..=29: refused whole, served as two 15,000-log halves.
        let logs: Vec<_> = (10u64..=29)
            .flat_map(|b| (0..1_500).map(move |li| transfer_log(b, li)))
            .collect();
        let source = ResultCapSource::new(logs, 15_000);
        let d = tempfile::tempdir().unwrap();
        let mut widest = 0u64;
        let total = backfill_direct_pipelined(
            &source,
            &reg,
            d.path(),
            &addresses,
            &topic0s,
            &[],
            None,
            0,
            10,
            29,
            1_000,
            SPAN_OFF,
            1,
            |_| Ok(()),
            |_, n, _| widest = widest.max(n),
        )
        .await
        .unwrap();
        assert_eq!(total, 30_000, "every row once");
        assert!(
            widest <= 20_000,
            "one window carried {widest} rows against a budget of 20,000"
        );
        let m = seal::load_manifest(d.path()).unwrap();
        let sealed: usize = m.tables.values().flatten().map(|s| s.rows).sum();
        assert_eq!(sealed, 30_000, "every row sealed once");

        // A right half whose first block alone is over what is left keeps that block whole: the
        // budget plus at most one block.
        let logs: Vec<_> = (10u64..=11)
            .flat_map(|b| (0..15_000).map(move |li| transfer_log(b, li)))
            .collect();
        let source = ResultCapSource::new(logs, 15_000);
        let d = tempfile::tempdir().unwrap();
        let mut widest = 0u64;
        let total = backfill_direct_pipelined(
            &source,
            &reg,
            d.path(),
            &addresses,
            &topic0s,
            &[],
            None,
            0,
            10,
            11,
            1_000,
            SPAN_OFF,
            1,
            |_| Ok(()),
            |_, n, _| widest = widest.max(n),
        )
        .await
        .unwrap();
        assert_eq!(total, 30_000, "an oversized block is kept, not dropped");
        assert!(
            widest <= 35_000,
            "{widest} rows: more than the budget plus one block"
        );
        let m = seal::load_manifest(d.path()).unwrap();
        let sealed: usize = m.tables.values().flatten().map(|s| s.rows).sum();
        assert_eq!(sealed, 30_000);
    }

    /// #1671: while the rest of a cut window is fetched, no further windows are issued, or every one
    /// that lands meanwhile waits in memory behind it.
    #[tokio::test]
    async fn no_window_is_issued_while_the_rest_of_a_cut_window_is_fetched() {
        use crate::registry::{ContractSpec, DecodeRegistry};
        const ERC20: &str = r#"[{"type":"event","name":"Transfer","inputs":[
            {"name":"from","type":"address","indexed":true},
            {"name":"to","type":"address","indexed":true},
            {"name":"value","type":"uint256","indexed":false}],"anonymous":false}]"#;
        let abi: alloy_json_abi::JsonAbi = serde_json::from_str(ERC20).unwrap();
        let reg = DecodeRegistry::build(vec![ContractSpec {
            alias: "usdc".into(),
            address: "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48"
                .parse()
                .unwrap(),
            abi,
            events: Vec::new(),
        }])
        .unwrap();
        let addresses: Vec<String> = reg
            .addresses()
            .iter()
            .map(|a| format!("0x{}", hex::encode(a)))
            .collect();
        let topic0s: Vec<String> = reg
            .topic0s()
            .iter()
            .map(|t| format!("0x{}", hex::encode(t)))
            .collect();
        // The dense run of the test above, then a long empty tail for windows to run ahead into.
        let logs: Vec<_> = (200_001u64..=215_000)
            .flat_map(|b| (0..3).map(move |li| transfer_log(b, li)))
            .collect();
        let mut source = ResultCapSource::new(logs, 1_000);
        source.max_calls = 20_000;
        let d = tempfile::tempdir().unwrap();
        backfill_direct_pipelined(
            &source,
            &reg,
            d.path(),
            &addresses,
            &topic0s,
            &[],
            None,
            0,
            0,
            2_000_000,
            1_000,
            SPAN_OFF,
            4,
            |_| Ok(()),
            |_, _, _| {},
        )
        .await
        .unwrap();
        let calls = source.calls.lock().unwrap().clone();
        let dense = |&(f, t): &(u64, u64)| f <= 215_000 && t >= 200_001;
        let last_dense = calls.iter().rposition(dense).unwrap();
        let cut_to = calls
            .iter()
            .filter(|c| dense(c))
            .map(|c| c.1)
            .max()
            .unwrap();
        let ahead = calls[..last_dense]
            .iter()
            .filter(|&&(f, _)| f > cut_to)
            .count();
        assert!(
            ahead <= 4,
            "{ahead} windows past block {cut_to} were asked for before the dense run was fetched"
        );
    }

    fn usdc_transfers() -> (DecodeRegistry, Vec<String>, Vec<String>) {
        use crate::registry::ContractSpec;
        const ERC20: &str = r#"[{"type":"event","name":"Transfer","inputs":[
            {"name":"from","type":"address","indexed":true},
            {"name":"to","type":"address","indexed":true},
            {"name":"value","type":"uint256","indexed":false}],"anonymous":false}]"#;
        let reg = DecodeRegistry::build(vec![ContractSpec {
            alias: "usdc".into(),
            address: "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48"
                .parse()
                .unwrap(),
            abi: serde_json::from_str(ERC20).unwrap(),
            events: Vec::new(),
        }])
        .unwrap();
        let addresses = reg
            .addresses()
            .iter()
            .map(|a| format!("0x{}", hex::encode(a)))
            .collect();
        let topic0s = reg
            .topic0s()
            .iter()
            .map(|t| format!("0x{}", hex::encode(t)))
            .collect();
        (reg, addresses, topic0s)
    }

    fn sealed_hashes(dir: &std::path::Path) -> Vec<(String, String)> {
        let m = seal::load_manifest(dir).unwrap();
        m.tables
            .iter()
            .flat_map(|(t, segs)| segs.iter().map(move |s| (t.clone(), s.hash.clone())))
            .collect()
    }

    /// #1787: a split lowers the ceiling to the piece that was served. Over a long empty tail after
    /// it the ceiling must climb back, not walk the tail at the piece's width.
    #[tokio::test]
    async fn the_ceiling_a_split_lowered_recovers_over_an_empty_tail() {
        let (reg, addresses, topic0s) = usdc_transfers();
        // 3,000 logs in the first 1,000 blocks against a 1,000-log cap, then nothing to 1,000,000.
        let logs: Vec<_> = (0u64..1_000)
            .flat_map(|b| (0..3).map(move |li| transfer_log(b, li)))
            .collect();
        let mut source = ResultCapSource::new(logs, 1_000);
        source.max_calls = usize::MAX;
        let d = tempfile::tempdir().unwrap();
        let total = backfill_direct_pipelined(
            &source,
            &reg,
            d.path(),
            &addresses,
            &topic0s,
            &[],
            None,
            0,
            0,
            1_000_000,
            1_000,
            SPAN_OFF,
            1,
            |_| Ok(()),
            |_, _, _| {},
        )
        .await
        .unwrap();
        assert_eq!(total, 3_000);
        // 4,005 calls while the ceiling stayed at the split's piece, 50 once it recovers.
        let calls = source.calls.lock().unwrap().len();
        assert!(calls <= 100, "{calls} getLogs calls over the empty tail");
    }

    /// Logs `ResultCapSource` served whole, per request.
    fn served_per_request(source: &ResultCapSource) -> Vec<usize> {
        source
            .calls
            .lock()
            .unwrap()
            .iter()
            .map(|&(from, to)| {
                let lo = source.logs.partition_point(|l| l.block_number < from);
                let hi = source.logs.partition_point(|l| l.block_number <= to);
                hi - lo
            })
            .filter(|&n| n <= source.cap)
            .collect()
    }

    /// #1788: the rest of a cut window asks for about as many blocks as the cut held, not for the rest
    /// of the window. Asking for the rest of the window has an uncapped node send it all again for each
    /// 20,000 logs kept, and has a capped one refuse it and split it down again every time.
    #[tokio::test]
    async fn the_rest_of_a_cut_window_asks_for_what_the_budget_can_hold() {
        let (reg, addresses, topic0s) = usdc_transfers();
        // Empty to 200,000, then 30,000 blocks at three logs each, then 55,000 empty blocks, all inside
        // the one 100,000-block window the controller has grown to by block 185,000.
        let logs: Vec<_> = (200_001u64..=230_000)
            .flat_map(|b| (0..3).map(move |li| transfer_log(b, li)))
            .collect();
        let run = |cap: usize| {
            let (reg, addresses, topic0s, logs) = (&reg, &addresses, &topic0s, logs.clone());
            async move {
                let source = ResultCapSource::new(logs, cap);
                let d = tempfile::tempdir().unwrap();
                let total = backfill_direct_pipelined(
                    &source,
                    reg,
                    d.path(),
                    addresses,
                    topic0s,
                    &[],
                    None,
                    0,
                    0,
                    285_000,
                    1_000,
                    SPAN_OFF,
                    1,
                    |_| Ok(()),
                    |_, _, _| {},
                )
                .await
                .unwrap();
                assert_eq!(total, 90_000, "every row once");
                (source, sealed_hashes(d.path()))
            }
        };

        // No cap: the window's first answer is all 90,000 logs, and nothing after it should be.
        let (uncapped, uncapped_hashes) = run(usize::MAX).await;
        let mut served = served_per_request(&uncapped);
        served.sort_unstable();
        let after_first = served[served.len() - 2];
        assert!(
            after_first <= SEAL_DIRECT_WINDOW_LOGS,
            "a remainder fetch was answered with {after_first} logs against a budget of {SEAL_DIRECT_WINDOW_LOGS}"
        );
        // Asking for the rest of the window each time downloads 250,020 logs, and asking for a fixed
        // width through the empty tail takes 20 requests.
        let downloaded: usize = served.iter().sum();
        assert!(
            downloaded <= 2 * 90_000,
            "{downloaded} logs downloaded to keep 90,000"
        );
        let requests = uncapped.calls.lock().unwrap().len();
        assert!(requests <= 16, "{requests} getLogs requests without a cap");

        // A cap above the budget, as `GETLOGS_BODY_CAP` makes of an uncapped node.
        let (capped, capped_hashes) = run(30_000).await;
        let requests = capped.calls.lock().unwrap().len();
        // 23 when each remainder is refused and split down again, 22 at a fixed width, 16 otherwise.
        assert!(
            requests <= 18,
            "{requests} getLogs requests against a 30,000-log cap"
        );

        let d = tempfile::tempdir().unwrap();
        backfill_direct(
            &ResultCapSource::new(logs.clone(), 30_000),
            &reg,
            d.path(),
            &addresses,
            &topic0s,
            &[],
            None,
            0,
            0,
            285_000,
            1_000,
            SPAN_OFF,
            true,
        )
        .await
        .unwrap();
        let reference = sealed_hashes(d.path());
        assert_eq!(uncapped_hashes, reference, "uncapped: the same bytes");
        assert_eq!(capped_hashes, reference, "capped: the same bytes");
    }

    /// #1788: a remainder narrowed by the budget was served whole, so it must not teach the
    /// controller that the provider caps the window at the remainder's width.
    #[tokio::test]
    async fn a_narrowed_remainder_does_not_lower_the_window_ceiling() {
        let (reg, addresses, topic0s) = usdc_transfers();
        let logs: Vec<_> = (200_001u64..=230_000)
            .flat_map(|b| (0..3).map(move |li| transfer_log(b, li)))
            .collect();
        let source = ResultCapSource::new(logs, usize::MAX);
        let d = tempfile::tempdir().unwrap();
        let mut widest_after = 0u64;
        backfill_direct_pipelined(
            &source,
            &reg,
            d.path(),
            &addresses,
            &topic0s,
            &[],
            None,
            0,
            0,
            1_000_000,
            1_000,
            SPAN_OFF,
            1,
            |_| Ok(()),
            |blk, _, window| {
                if blk > 300_000 {
                    widest_after = widest_after.max(window)
                }
            },
        )
        .await
        .unwrap();
        assert_eq!(
            widest_after,
            chunker::MAX_WINDOW,
            "the empty range after the dense run should grow the window back to the ceiling"
        );
    }

    /// An `eth_getLogs` node with no result cap, serving `logs` over HTTP (#1788). Every log carries
    /// `blockTimestamp`, so no header is asked for.
    async fn uncapped_node(logs: Vec<crate::rpc::Log>) -> (String, tokio::task::JoinHandle<()>) {
        use axum::{extract::State, routing::post, Json, Router};
        use serde_json::{json, Value};
        async fn handler(
            State(logs): State<Arc<Vec<crate::rpc::Log>>>,
            Json(req): Json<Value>,
        ) -> Json<Value> {
            let hex = |v: &Value| {
                u64::from_str_radix(v.as_str().unwrap().trim_start_matches("0x"), 16).unwrap()
            };
            let one = |r: &Value| -> Value {
                let result = match r["method"].as_str() {
                    Some("eth_getLogs") => {
                        let f = &r["params"][0];
                        let (from, to) = (hex(&f["fromBlock"]), hex(&f["toBlock"]));
                        let set = |v: &Value| -> Option<Vec<String>> {
                            v.as_array().map(|a| {
                                a.iter()
                                    .map(|x| x.as_str().unwrap().to_ascii_lowercase())
                                    .collect()
                            })
                        };
                        let addresses = set(&f["address"]);
                        let topic0s = set(&f["topics"][0]);
                        Value::Array(
                            logs.iter()
                                .filter(|l| (from..=to).contains(&l.block_number))
                                .filter(|l| {
                                    addresses
                                        .as_ref()
                                        .is_none_or(|a| a.contains(&l.address.to_ascii_lowercase()))
                                })
                                .filter(|l| {
                                    topic0s.as_ref().is_none_or(|t| {
                                        l.topics
                                            .first()
                                            .is_some_and(|t0| t.contains(&t0.to_ascii_lowercase()))
                                    })
                                })
                                .map(|l| {
                                    json!({
                                        "address": l.address,
                                        "topics": l.topics,
                                        "data": l.data,
                                        "blockNumber": format!("0x{:x}", l.block_number),
                                        "blockHash": l.block_hash,
                                        "blockTimestamp": format!("0x{:x}", l.block_number * 12),
                                        "transactionHash": l.tx_hash,
                                        "logIndex": format!("0x{:x}", l.log_index),
                                    })
                                })
                                .collect(),
                        )
                    }
                    Some("eth_getBlockByNumber") => {
                        let b = hex(&r["params"][0]);
                        json!({
                            "number": format!("0x{b:x}"),
                            "hash": format!("0x{b:064x}"),
                            "timestamp": format!("0x{:x}", b * 12),
                        })
                    }
                    _ => Value::Null,
                };
                json!({"jsonrpc": "2.0", "id": r["id"], "result": result})
            };
            Json(match &req {
                Value::Array(rs) => Value::Array(rs.iter().map(one).collect()),
                r => one(r),
            })
        }
        let app = Router::new()
            .route("/", post(handler))
            .with_state(Arc::new(logs));
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let handle = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });
        (format!("http://{addr}/"), handle)
    }

    /// A source that remembers the most logs one `getLogs` answer handed the backfill, and panics when
    /// one range is refused `MAX_SAME_REFUSALS` times running: a refusal the backfill does not narrow
    /// for is retried at that width forever, and the test would hang rather than fail.
    struct Largest<'a> {
        inner: &'a dyn Source,
        most: std::sync::atomic::AtomicUsize,
        refused: std::sync::Mutex<((u64, u64), usize)>,
    }

    const MAX_SAME_REFUSALS: usize = 4;

    impl<'a> Largest<'a> {
        fn new(inner: &'a dyn Source) -> Self {
            Self {
                inner,
                most: Default::default(),
                refused: Default::default(),
            }
        }
        fn most(&self) -> usize {
            self.most.load(std::sync::atomic::Ordering::SeqCst)
        }
    }

    #[async_trait::async_trait]
    impl Source for Largest<'_> {
        async fn tip(&self) -> Result<u64> {
            self.inner.tip().await
        }
        async fn block_hash(&self, n: u64) -> Result<Option<String>> {
            self.inner.block_hash(n).await
        }
        async fn block_timestamps(
            &self,
            blocks: &[u64],
        ) -> Result<std::collections::HashMap<u64, u64>> {
            self.inner.block_timestamps(blocks).await
        }
        async fn logs(
            &self,
            filter: &crate::source::LogFilter,
            from: u64,
            to: u64,
        ) -> Result<Vec<crate::rpc::Log>> {
            let answer = self.inner.logs(filter, from, to).await;
            {
                let mut refused = self.refused.lock().unwrap();
                *refused = match (&answer, *refused) {
                    (Ok(_), _) => ((from, to), 0),
                    (Err(_), (range, n)) if range == (from, to) => (range, n + 1),
                    (Err(_), _) => ((from, to), 1),
                };
                assert!(
                    refused.1 < MAX_SAME_REFUSALS,
                    "{from}..={to} refused {} times running: the backfill is not narrowing",
                    refused.1
                );
            }
            let logs = answer?;
            self.most
                .fetch_max(logs.len(), std::sync::atomic::Ordering::SeqCst);
            Ok(logs)
        }
    }

    /// The test's body cap, and the most fixture logs it admits in one answer.
    const TEST_BODY_CAP: usize = 128 << 10;

    fn logs_under_test_cap(sample: &crate::rpc::Log) -> usize {
        let one = serde_json::json!({
            "address": sample.address,
            "topics": sample.topics,
            "data": sample.data,
            "blockNumber": format!("0x{:x}", sample.block_number),
            "blockHash": sample.block_hash,
            "blockTimestamp": format!("0x{:x}", sample.block_number * 12),
            "transactionHash": sample.tx_hash,
            "logIndex": "0x0",
        });
        TEST_BODY_CAP / serde_json::to_vec(&one).unwrap().len()
    }

    /// Dense from 200,001, after an empty run the window grows across: 6,000 transfers.
    fn dense_after_empty() -> Vec<crate::rpc::Log> {
        (200_001u64..=202_000)
            .flat_map(|b| (0..3).map(move |li| transfer_log(b, li)))
            .collect()
    }

    /// #1788: the pipelined path against a node with no result cap. The leaf's cut bounds what is
    /// kept, but only the body cap bounds what one answer brings.
    #[tokio::test]
    async fn the_pipelined_path_reads_no_answer_past_the_body_cap_from_an_uncapped_node() {
        let (reg, addresses, topic0s) = usdc_transfers();
        let logs = dense_after_empty();
        let bound = logs_under_test_cap(&logs[0]);
        let (url, server) = uncapped_node(logs).await;
        let mut hashes = Vec::new();
        for cap in [TEST_BODY_CAP, usize::MAX] {
            let rpc = crate::rpc::RpcClient::new(vec![url.clone()])
                .unwrap()
                .with_logs_body_cap(cap);
            let source = Largest::new(&rpc);
            let d = tempfile::tempdir().unwrap();
            let total = backfill_direct_pipelined(
                &source,
                &reg,
                d.path(),
                &addresses,
                &topic0s,
                &[],
                None,
                0,
                0,
                210_000,
                1_000,
                SPAN_OFF,
                1,
                |_| Ok(()),
                |_, _, _| {},
            )
            .await
            .unwrap();
            assert_eq!(total, 6_000, "every row once");
            if cap == TEST_BODY_CAP {
                assert!(
                    source.most() <= bound,
                    "one answer carried {} logs; the cap admits {bound}",
                    source.most()
                );
            }
            hashes.push(sealed_hashes(d.path()));
        }
        server.abort();
        assert_eq!(
            hashes[0], hashes[1],
            "the cap must not change the sealed bytes"
        );
    }

